-- Schema of the Neon project Pool Geek® Manufacturer Catalog (still-union-48288873), taken from the live
-- tables on 2026-10-26. Run once on an empty database; then scripts/load_neon.py fills it.
CREATE SCHEMA IF NOT EXISTS mfr_catalog;
CREATE TABLE mfr_catalog.products (mpn text NOT NULL, brand text NOT NULL, title text NOT NULL, kind text NOT NULL, status text NOT NULL, replaced_by text, product_line text, parent_product text, fits text, title_pdf_page integer NOT NULL, pages text NOT NULL, needs_review boolean NOT NULL, review_notes text, source text NOT NULL, PRIMARY KEY (mpn));
CREATE TABLE mfr_catalog.evidence (mpn text NOT NULL, pdf_page integer NOT NULL, printed_page text, page_type text, brand text, title text, kind text, status text, source_row text, context text, confidence text, notes text);
CREATE TABLE mfr_catalog.conflicts (mpn text NOT NULL, field text NOT NULL, values_by_page jsonb NOT NULL);
CREATE TABLE mfr_catalog.attributes (key text NOT NULL, unit text, meaning text, controlled integer NOT NULL, spec_count integer NOT NULL, PRIMARY KEY (key));
CREATE TABLE mfr_catalog.cross_references (mpn text NOT NULL, brand text, number text NOT NULL, pdf_page integer NOT NULL);
CREATE TABLE mfr_catalog.data_issues (batch text NOT NULL, pdf_page integer, mpn text, question text NOT NULL);
CREATE TABLE mfr_catalog.derived_specs (mpn text NOT NULL, attr text NOT NULL, value text NOT NULL, basis text NOT NULL, source text NOT NULL);
CREATE TABLE mfr_catalog.document_links (document_id integer NOT NULL, family_id text, mpn text, page_url text NOT NULL, via text NOT NULL);
CREATE TABLE mfr_catalog.documents (id integer NOT NULL, url text NOT NULL, title text NOT NULL, kind text NOT NULL, lang text NOT NULL, local_file text, bytes integer, object_key text, public_url text, PRIMARY KEY (id));
CREATE TABLE mfr_catalog.excluded_mpns (mpn text NOT NULL, status text NOT NULL, PRIMARY KEY (mpn));
CREATE TABLE mfr_catalog.families (id text NOT NULL, name text NOT NULL, brand text, parent text, category text, description text, features jsonb NOT NULL, notes jsonb NOT NULL, parts_pages jsonb NOT NULL, pages jsonb NOT NULL, PRIMARY KEY (id));
CREATE TABLE mfr_catalog.family_links (family_id text NOT NULL, linked_to text NOT NULL, source text NOT NULL);
CREATE TABLE mfr_catalog.fitment (part_mpn text NOT NULL, family_ids jsonb NOT NULL, models jsonb NOT NULL, mpns jsonb NOT NULL, item text, qty double precision, condition text, raw text, pdf_page integer NOT NULL);
CREATE TABLE mfr_catalog.image_links (image_id integer NOT NULL, family_id text, mpn text, page_url text NOT NULL, via text NOT NULL);
CREATE TABLE mfr_catalog.images (id integer NOT NULL, url text NOT NULL, alt text, role text NOT NULL, local_file text, width integer, height integer, bytes integer, label text, people integer, background text, object_key text, public_url text, PRIMARY KEY (id));
CREATE TABLE mfr_catalog.model_parts (model_mpn text NOT NULL, part_mpn text NOT NULL, family_id text NOT NULL, item text, qty double precision, condition text, pdf_page integer NOT NULL);
CREATE TABLE mfr_catalog.prices (mpn text NOT NULL, us_list numeric, can_list numeric, price_note text, pdf_page integer NOT NULL);
CREATE TABLE mfr_catalog.product_families (mpn text NOT NULL, family_id text, role text NOT NULL, band text, pdf_page integer NOT NULL);
CREATE TABLE mfr_catalog.product_prices (mpn text NOT NULL, us_list numeric, can_list numeric, price_note text, basis text NOT NULL, pages text NOT NULL, PRIMARY KEY (mpn));
CREATE TABLE mfr_catalog.reference_tables (id integer NOT NULL, kind text NOT NULL, family_ids jsonb NOT NULL, title text, columns jsonb, rows jsonb, summary text, pdf_page integer NOT NULL, PRIMARY KEY (id));
CREATE TABLE mfr_catalog.replacements (old_mpn text NOT NULL, mpn text NOT NULL, raw text, pdf_page integer NOT NULL);
CREATE TABLE mfr_catalog.specs (mpn text NOT NULL, attr text NOT NULL, value text NOT NULL, value_num double precision, unit text, raw text, pdf_page integer NOT NULL);
ALTER TABLE mfr_catalog.documents ADD CONSTRAINT documents_url_key UNIQUE (url);
ALTER TABLE mfr_catalog.images ADD CONSTRAINT images_url_key UNIQUE (url);
ALTER TABLE mfr_catalog.conflicts ADD CONSTRAINT conflicts_mpn_fkey FOREIGN KEY (mpn) REFERENCES mfr_catalog.products(mpn) ON DELETE CASCADE;
ALTER TABLE mfr_catalog.evidence ADD CONSTRAINT evidence_mpn_fkey FOREIGN KEY (mpn) REFERENCES mfr_catalog.products(mpn) ON DELETE CASCADE;
CREATE INDEX cross_references_number_idx ON mfr_catalog.cross_references USING btree (number);
CREATE INDEX derived_specs_mpn_idx ON mfr_catalog.derived_specs USING btree (mpn);
CREATE INDEX document_links_family_idx ON mfr_catalog.document_links USING btree (family_id);
CREATE INDEX evidence_mpn_idx ON mfr_catalog.evidence USING btree (mpn);
CREATE INDEX fitment_family_idx ON mfr_catalog.fitment USING gin (family_ids);
CREATE INDEX fitment_part_idx ON mfr_catalog.fitment USING btree (part_mpn);
CREATE INDEX image_links_family_idx ON mfr_catalog.image_links USING btree (family_id);
CREATE INDEX model_parts_model_idx ON mfr_catalog.model_parts USING btree (model_mpn);
CREATE INDEX model_parts_part_idx ON mfr_catalog.model_parts USING btree (part_mpn);
CREATE INDEX product_families_idx ON mfr_catalog.product_families USING btree (family_id);
CREATE INDEX replacements_old_idx ON mfr_catalog.replacements USING btree (old_mpn);
CREATE INDEX specs_attr_idx ON mfr_catalog.specs USING btree (attr, value_num);
CREATE INDEX specs_mpn_idx ON mfr_catalog.specs USING btree (mpn);
